classdef LinearFirstOrderTest < matlab.unittest.TestCase
%LINEARFIRSTORDERTEST  Analytic, property and update tests for the entry-point model.
%
%   Layers 1 and 2 of the project's test plan. The anchor is the ANALYTIC step response: the
%   discrete recursion is ZOH-exact, so it must reproduce the continuous
%   first-order solution y(t) = K*u*(1 - exp(-t/T)) EXACTLY at the sample instants,
%   not approximately. That single assertion pins the pole, the input gain and the
%   output equation simultaneously.
%
%   The second anchor is the fit-back test: noise-free data generated by a
%   different first-order system must be recovered to machine precision. An
%   equation-error least squares fit on data from an exact ARX process is an exact
%   identity, so anything less than 1e-10 means the parameter mapping
%   (a, b, e) -> (T, gain, offset) is wrong.

    properties (Constant)
        T    = 2
        TS   = 0.1
        Gain = 3
        Tol  = 1e-12
    end

    methods (Access = private)
        function srg = plainModel(tc)
            srg = rid.surrogate.LinearFirstOrder(tc.T, tc.TS, tc.Gain);
        end
        function rs = stream(~, seed)
            rs = RandStream("twister", "Seed", seed);
        end
    end

    methods (Test)

        % --- the batch layout is not "always 3-D" ---------------------

        function simulateBatchAcceptsATwoDimensionalSingleSequenceBatchSiso(tc)
            % MATLAB TRIMS TRAILING SINGLETONS, so a one-sequence batch reaches
            % simulateBatch as a 2-D (nHorizon x nInputs) array and NO caller can
            % make it 3-D. The documentation used to claim the layout was always
            % 3-D, which no caller could satisfy.
            %
            % Fails if: anything starts asserting ndims(uSeqBatch) == 3.
            srg  = tc.plainModel();
            uSeq = [0; 1; 1; 0.5; 0.5; 2];              % (6 x 1), a 2-D batch
            tc.assertEqual(ndims(uSeq), 2, ...
                "fixture must be 2-D or the test proves nothing");

            [Y, Xend] = srg.simulateBatch(uSeq, 0.3);
            [y, xEnd] = srg.simulate(uSeq, 0.3);
            tc.verifyEqual(Y, y, "AbsTol", tc.Tol);
            tc.verifyEqual(Xend, xEnd, "AbsTol", tc.Tol);
            tc.verifyEqual(size(Y, 2), 1);              % one sequence
        end

        function simulateBatchAcceptsATwoDimensionalSingleSequenceBatchMiso(tc)
            % The MISO case is where the ambiguity actually lives: (6 x 2)
            % must be read as ONE two-input sequence, not two SISO sequences. What
            % settles it is size(uSeqBatch, 2) == nInputs -- the check
            % assertBatchShape has always made -- not the number of dimensions.
            %
            % Fails if: dimension 2 is read as the sequence index for a 2-D batch.
            srg  = rid.surrogate.LinearFirstOrder(tc.T, tc.TS, [tc.Gain, -1]);
            uSeq = [0 1; 1 0; 1 1; 0.5 2; 0.5 0; 2 -1];  % (6 x 2), ONE sequence
            tc.assertEqual(ndims(uSeq), 2);

            [Y, Xend] = srg.simulateBatch(uSeq, 0.3);
            [y, xEnd] = srg.simulate(uSeq, 0.3);
            tc.verifyEqual(size(Y), [6, 1], ...
                "a (6 x 2) MISO batch is one sequence, not two");
            tc.verifyEqual(Y, y, "AbsTol", tc.Tol);
            tc.verifyEqual(Xend, xEnd, "AbsTol", tc.Tol);
        end

        function aSisoBatchOfSeveralSequencesIsGenuinelyThreeDimensional(tc)
            % The other half: a MIDDLE singleton is never trimmed, so
            % (nHorizon x 1 x nSeq) stays 3-D on its own. Both shapes are legal and
            % which one arrives is decided by nSeq, not by a convention.
            srg  = tc.plainModel();
            batch = cat(3, [0; 1; 1; 0.5], [1; 0; 0.5; 2], [2; 2; 0; 0]);
            tc.assertEqual(size(batch), [4 1 3]);
            tc.assertEqual(ndims(batch), 3);

            Y = srg.simulateBatch(batch, 0.3);
            tc.verifyEqual(size(Y), [4, 3]);
            for iSeq = 1:3
                tc.verifyEqual(Y(:, iSeq), srg.simulate(batch(:, :, iSeq), 0.3), ...
                    "AbsTol", tc.Tol);
            end
        end

        % --- the analytic step response --------------------------------------

        function stepResponseMatchesTheContinuousSolutionExactly(tc)
            srg      = tc.plainModel();
            nHorizon = 60;
            uStep    = ones(nHorizon, 1);
            yHat     = srg.simulate(uStep, 0);

            t        = (0:nHorizon-1).' * tc.TS;
            expected = tc.Gain * (1 - exp(-t / tc.T));

            tc.verifyEqual(yHat, expected, "RelTol", tc.Tol, "AbsTol", tc.Tol);
            tc.verifyEqual(yHat(1), 0, "AbsTol", tc.Tol);   % strictly proper: no jump
        end

        function stepResponseMatchesTheDiscreteClosedForm(tc)
            srg    = tc.plainModel();
            a      = exp(-tc.TS / tc.T);
            yHat = srg.simulate(2 * ones(25, 1), 0);
            kStep  = (0:24).';
            tc.verifyEqual(yHat, tc.Gain * 2 * (1 - a.^kStep), ...
                "RelTol", tc.Tol, "AbsTol", tc.Tol);
        end

        function aDirectTermMakesTheOutputJumpAtTheFirstSample(tc)
            % the strictly proper default does not jump; a direct term is
            % available for a process with an algebraic path, and the static gain
            % then splits as gain = b/(1-a) + directTerm.
            srg    = rid.surrogate.LinearFirstOrder(tc.T, tc.TS, tc.Gain, ...
                "directTerm", 0.5);
            yHat = srg.simulate(ones(4000, 1), 0);
            tc.verifyEqual(yHat(1), 0.5, "AbsTol", tc.Tol);
            tc.verifyEqual(yHat(end), tc.Gain, "RelTol", 1e-8);
        end

        % --- purity and value semantics --------------------------------------

        function simulateIsPureAndRepeatable(tc)
            srg  = tc.plainModel();
            rs   = tc.stream(1);
            uSeq = rand(rs, 40, 1);
            [y1, x1] = srg.simulate(uSeq, 0.25);
            [y2, x2] = srg.simulate(uSeq, 0.25);
            tc.verifyEqual(y1, y2);   % bit-identical, not merely close
            tc.verifyEqual(x1, x2);
        end

        function theTerminalStateResumesTheSimulation(tc)
            % "State in, state out": splitting a simulation must be identical to
            % running it whole. This is what lets the loop carry the state forward
            % across steps.
            srg  = tc.plainModel();
            rs   = tc.stream(2);
            uSeq = rand(rs, 30, 1);
            yAll = srg.simulate(uSeq, 0.4);

            [yA, xMid] = srg.simulate(uSeq(1:12, :), 0.4);
            yB         = srg.simulate(uSeq(13:end, :), xMid);
            tc.verifyEqual([yA; yB], yAll, "AbsTol", tc.Tol);
        end

        function anEmptyHorizonReturnsTheStateUnchanged(tc)
            srg = tc.plainModel();
            [yHat, xEnd] = srg.simulate(zeros(0, 1), 0.7);
            tc.verifyEqual(size(yHat), [0 1]);
            tc.verifyEqual(xEnd, 0.7);
        end

        function xStartIsRequiredAndShapeChecked(tc)
            srg = tc.plainModel();
            tc.verifyError(@() srg.simulate(ones(5, 1), [0 0]), ...
                "rid:surrogate:dimensionMismatch");
            tc.verifyError(@() srg.simulate(ones(5, 2), 0), ...
                "rid:surrogate:dimensionMismatch");
        end

        function isValueClassNotHandle(tc)
            tc.verifyFalse(isa(tc.plainModel(), "handle"));
        end

        % --- physical units ------------------------------------------

        function theModelWorksInPhysicalUnitsWithNoHiddenNormalization(tc)
            % Doubling the gain doubles the output exactly. If any normalization
            % had crept inside the model, this ratio would not be 2.
            uSeq = linspace(0, 1, 40).';
            y1 = rid.surrogate.LinearFirstOrder(tc.T, tc.TS, 1).simulate(uSeq, 0);
            y2 = rid.surrogate.LinearFirstOrder(tc.T, tc.TS, 2).simulate(uSeq, 0);
            tc.verifyEqual(y2, 2 * y1, "AbsTol", tc.Tol);
        end

        % --- steadyState, the canonical producer of xStart -----------

        function steadyStateIsTheRestStateOfAConstantInput(tc)
            srg = rid.surrogate.LinearFirstOrder(tc.T, tc.TS, tc.Gain, "offset", -1);
            for uConst = [-2, 0, 1.5]
                x = srg.steadyState(uConst);
                tc.verifyEqual(x, tc.Gain * uConst - 1, "AbsTol", tc.Tol);
                % Starting there, the state never moves: that is what "rest" means.
                [~, xEnd] = srg.simulate(repmat(uConst, 500, 1), x);
                tc.verifyEqual(xEnd, x, "AbsTol", 1e-10);
            end
        end

        function aLongConstantInputConvergesToSteadyState(tc)
            srg = rid.surrogate.LinearFirstOrder(tc.T, tc.TS, tc.Gain, "offset", 0.5);
            [~, xEnd] = srg.simulate(0.8 * ones(4000, 1), 0);
            tc.verifyEqual(xEnd, srg.steadyState(0.8), "RelTol", 1e-10);
        end

        % --- the ROI-derived gain ------------------------------------

        function fromRoiSpansTheRoiDiagonal(tc)
            % The reason the derived gain exists: with a gain of 1 against this ROI, every
            % predicted point would sit in the bottom tenth of the output
            % dimension, and the design would believe most of the ROI unreachable.
            roi = struct("u1_k", [0 1], "du1_k", [-0.2 0.2], "y_km1", [-5 5]);
            srg = rid.surrogate.LinearFirstOrder.fromRoi(roi, tc.T, tc.TS);

            tc.verifyEqual(srg.gain, 10, "AbsTol", tc.Tol);     % (5-(-5))/(1*(1-0))
            % The static map takes the ROI's input range onto its output range,
            % with the equilibrium through the ROI centre.
            tc.verifyEqual(srg.steadyState(0), -5, "AbsTol", tc.Tol);
            tc.verifyEqual(srg.steadyState(1),  5, "AbsTol", tc.Tol);
            tc.verifyEqual(srg.steadyState(0.5), 0, "AbsTol", tc.Tol);
        end

        function fromRoiSplitsTheDiagonalAcrossSeveralInputs(tc)
            roi = struct("u1_k", [0 2], "u2_k", [-1 1], "y_km1", [0 8]);
            srg = rid.surrogate.LinearFirstOrder.fromRoi(roi, tc.T, tc.TS, ...
                "inputName", ["u1_k" "u2_k"]);
            tc.verifyEqual(srg.nInputs, 2);
            tc.verifyEqual(srg.gain, [8/(2*2), 8/(2*2)], "AbsTol", tc.Tol);
            % All inputs at their minimum -> the ROI's output minimum; all at
            % their maximum -> its maximum.
            tc.verifyEqual(srg.steadyState([0 -1]), 0, "AbsTol", tc.Tol);
            tc.verifyEqual(srg.steadyState([2  1]), 8, "AbsTol", tc.Tol);
        end

        function fromRoiIgnoresRangesItDoesNotSpan(tc)
            % fromRoi is a MODEL constructor, not a representation: it consumes the
            % ranges its static map spans and no others. "du1" belongs to the
            % coordinate system, not to the dynamics.
            roi = struct("u1_k", [0 1], "du1_k", [-0.2 0.2], "y_km1", [-5 5]);
            withDu    = rid.surrogate.LinearFirstOrder.fromRoi(roi, tc.T, tc.TS);
            withoutDu = rid.surrogate.LinearFirstOrder.fromRoi( ...
                rmfield(roi, "du1_k"), tc.T, tc.TS);
            tc.verifyEqual(withDu.gain, withoutDu.gain);
            tc.verifyEqual(withDu.offset, withoutDu.offset);
        end

        function fromRoiNeedsTheRangesItSpans(tc)
            % The identifier names the package that THROWS: this is the
            % surrogate reading a declaration, not a representation validating one.
            tc.verifyError(@() rid.surrogate.LinearFirstOrder.fromRoi( ...
                struct("u1_k", [0 1]), tc.T, tc.TS), "rid:surrogate:missingRange");
            tc.verifyError(@() rid.surrogate.LinearFirstOrder.fromRoi( ...
                struct("y_km1", [0 1]), tc.T, tc.TS), "rid:surrogate:missingRange");
            % A zero-width or unordered range is kept as an error here, unlike in
            % rep.bounds, because the ROI-derived gain DIVIDES by the width.
            tc.verifyError(@() rid.surrogate.LinearFirstOrder.fromRoi( ...
                struct("u1_k", [1 0], "y_km1", [0 1]), tc.T, tc.TS), ...
                "rid:surrogate:invalidRange");
        end

        function fromRoiReadsTheLevelCoordinateItIsGiven(tc)
            % Under the declared-bounds rule different lags of the same channel may carry different
            % ranges, so "the input range" is no longer unambiguous: the caller
            % names the coordinate the static map spans. A representation with
            % another input delay passes its own name.
            roi = struct("u1_km1", [0 1], "u1_km2", [0 100], "y_km1", [-5 5]);
            srg = rid.surrogate.LinearFirstOrder.fromRoi(roi, tc.T, tc.TS, ...
                "inputName", "u1_km1");
            tc.verifyEqual(srg.gain, 10, "AbsTol", tc.Tol);   % from u1_km1, not u1_km2
        end

        function fromRoiDefaultsToTheDefaultRepresentationsCoordinates(tc)
            % The defaults track the naming convention and the default input delay
            % rather than being spelled out as literals.
            rep = rid.rep.Narx(2, 1);
            tc.verifyTrue(all(ismember(["u1_k" "y_km1"], rep.requiredNames())));
        end

        % --- update -------------------------------------------

        function updateRecoversTheGeneratingParameters(tc)
            % Noise-free data from a DIFFERENT first-order system. Equation-error
            % least squares on data from an exact ARX process is an identity, so
            % anything worse than 1e-10 means the mapping
            % (a, b, e) -> (timeConstant, gain, offset) is wrong.
            truth = rid.surrogate.LinearFirstOrder(0.7, tc.TS, 2.5, "offset", -0.3);
            rs    = tc.stream(11);
            u     = 2 * rand(rs, 400, 1) - 1;
            y     = truth.simulate(u, truth.steadyState(u(1, :)));
            hist  = wellFormedHistory(u, "y", y, "tS", tc.TS);

            fitted = tc.plainModel().update(hist);

            tc.verifyEqual(fitted.timeConstant, truth.timeConstant, "RelTol", 1e-10);
            tc.verifyEqual(fitted.gain,         truth.gain,         "RelTol", 1e-10);
            tc.verifyEqual(fitted.offset,       truth.offset,       "AbsTol", 1e-10);
            tc.verifyEqual(fitted.tS,           tc.TS);
        end

        function updateReturnsANewObjectAndLeavesTheOriginalUntouched(tc)
            % Value semantics: the swap is
            % safe precisely because nothing mutates under the loop.
            truth = rid.surrogate.LinearFirstOrder(0.7, tc.TS, 2.5);
            rs    = tc.stream(12);
            u     = rand(rs, 200, 1);
            hist  = wellFormedHistory(u, "y", truth.simulate(u, 0), "tS", tc.TS);

            srg    = tc.plainModel();
            before = srg.describe();
            fitted = srg.update(hist);

            tc.verifyEqual(srg.describe(), before);
            tc.verifyEqual(srg.timeConstant, tc.T);
            tc.verifyNotEqual(fitted.timeConstant, srg.timeConstant);
        end

        function anUnstableUpdateIsRejected(tc)
            % |a| >= 1: the horizon simulation would diverge and J would become
            % meaningless, so the update is refused rather than silently accepted.
            rs   = tc.stream(13);
            hist = tc.arxHistory(1.05, 0.5, rs);
            tc.verifyError(@() tc.plainModel().update(hist), ...
                "rid:surrogate:unstableUpdate");
        end

        function aStableButUnrepresentableUpdateIsRejectedSeparately(tc)
            % a <= 0 is STABLE but has no real positive time constant, so it lies
            % outside this model class. Reporting it as "unstable" would be a false
            % statement in the event log, which is why the two-identifier update message keeps two identifiers.
            rs   = tc.stream(14);
            hist = tc.arxHistory(-0.5, 0.5, rs);
            tc.verifyError(@() tc.plainModel().update(hist), ...
                "rid:surrogate:invalidUpdate");
        end

        function aRejectedUpdateNeverReturnsAModel(tc)
            rs   = tc.stream(15);
            hist = tc.arxHistory(1.05, 0.5, rs);
            srg  = tc.plainModel();
            try
                srg.update(hist);
                tc.verifyFail("the unstable fit was accepted");
            catch err
                tc.verifyEqual(string(err.identifier), "rid:surrogate:unstableUpdate");
            end
            tc.verifyEqual(srg.timeConstant, tc.T);   % unchanged
            tc.verifyTrue(srg.isStable());
        end

        function tooLittleDataIsRejected(tc)
            rs   = tc.stream(16);
            u    = rand(rs, 5, 1);
            hist = wellFormedHistory(u, "y", tc.plainModel().simulate(u, 0), "tS", tc.TS);
            tc.verifyError(@() tc.plainModel().update(hist), ...
                "rid:surrogate:insufficientData");
        end

        function anUnexcitedHistoryIsRejectedRatherThanFittedBlindly(tc)
            % A constant input makes the regression matrix rank deficient. MATLAB's
            % backslash would return a least-norm solution with only a warning; the
            % model refuses instead, because a surrogate fitted to an
            % under-determined problem is worse than the one already in hand.
            u    = ones(200, 1);
            hist = wellFormedHistory(u, "y", tc.plainModel().simulate(u, 0), "tS", tc.TS);
            tc.verifyError(@() tc.plainModel().update(hist), ...
                "rid:surrogate:insufficientData");
        end

        function offlineHasNothingToRefitOn(tc)
            % Row 1 of the rebuild table: offline, the surrogate never changes
            % because there is nothing to fit it to.
            hist = wellFormedHistory(ones(50, 1), "y", [], "tS", tc.TS);
            tc.verifyError(@() tc.plainModel().update(hist), ...
                "rid:surrogate:insufficientData");
        end

        function aFeedthroughModelRefitsAllOfItsParameters(tc)
            % A feedthrough model IS identifiable when the excitation separates
            % u(k) from u(k-1); substituting x(k) = y(k) - d*u(k) turns it into the
            % same kind of least-squares problem with one block more. Refusing the
            % whole class in advance would refuse the identifiable case with it.
            truth = rid.surrogate.LinearFirstOrder(0.7, tc.TS, 2.5, ...
                "offset", -0.3, "directTerm", 0.4);
            rs   = tc.stream(17);
            u    = 2 * rand(rs, 400, 1) - 1;
            hist = wellFormedHistory(u, ...
                "y", truth.simulate(u, truth.steadyState(u(1, :))), "tS", tc.TS);

            start  = rid.surrogate.LinearFirstOrder(tc.T, tc.TS, tc.Gain, ...
                "directTerm", 0.1);
            fitted = start.update(hist);

            tc.verifyEqual(fitted.timeConstant, truth.timeConstant, "RelTol", 1e-10);
            tc.verifyEqual(fitted.gain,         truth.gain,         "RelTol", 1e-10);
            tc.verifyEqual(fitted.offset,       truth.offset,       "AbsTol", 1e-10);
            tc.verifyEqual(fitted.directTerm,   truth.directTerm,   "RelTol", 1e-10);
        end

        function theRefitPreservesTheDeclaredModelStructure(tc)
            % The regression form follows the model's declared structure, so an
            % update can never introduce a feedthrough path the user did not
            % declare -- and never silently drop one they did.
            rs = tc.stream(18);
            u  = 2 * rand(rs, 300, 1) - 1;

            proper = rid.surrogate.LinearFirstOrder(0.7, tc.TS, 2.5);
            hProper = wellFormedHistory(u, "y", proper.simulate(u, 0), "tS", tc.TS);
            tc.verifyEqual(tc.plainModel().update(hProper).directTerm, 0);

            direct = rid.surrogate.LinearFirstOrder(0.7, tc.TS, 2.5, ...
                "directTerm", 0.4);
            hDirect = wellFormedHistory(u, "y", direct.simulate(u, 0), "tS", tc.TS);
            start   = rid.surrogate.LinearFirstOrder(tc.T, tc.TS, tc.Gain, ...
                "directTerm", 0.1);
            tc.verifyNotEqual(start.update(hDirect).directTerm, 0);
        end

        function anUnidentifiableFeedthroughFitIsCaughtByTheRankGuard(tc)
            % The unidentifiable case is detected FROM THE DATA, not assumed from
            % the structure: an input held constant makes u(k) and u(k-1)
            % collinear, and the existing rank guard rejects the fit.
            srg  = rid.surrogate.LinearFirstOrder(tc.T, tc.TS, tc.Gain, ...
                "directTerm", 0.4);
            u    = ones(200, 1);
            hist = wellFormedHistory(u, "y", srg.simulate(u, 0), "tS", tc.TS);

            tc.verifyTrue(srg.canUpdate());
            tc.verifyError(@() srg.update(hist), "rid:surrogate:insufficientData");
        end

        function bothStructuresDeclareThatTheyCanRefit(tc)
            tc.verifyTrue(tc.plainModel().canUpdate());
            tc.verifyTrue(rid.surrogate.LinearFirstOrder(tc.T, tc.TS, tc.Gain, ...
                "directTerm", 0.5).canUpdate());
        end

        % --- stability and capabilities --------------------------------------

        function aConstructedModelIsAlwaysStable(tc)
            % The constructor enforces timeConstant > 0, so 0 < a < 1 holds by
            % construction and isStable only ever bites on an update -- which is
            % exactly where it must.
            for tConst = [1e-3, 0.1, 1, 1e4]
                srg = rid.surrogate.LinearFirstOrder(tConst, tc.TS, 1);
                tc.verifyTrue(srg.isStable());
                tc.verifyGreaterThan(srg.a, 0);
                tc.verifyLessThan(srg.a, 1);
            end
            tc.verifyError(@() rid.surrogate.LinearFirstOrder(-1, tc.TS, 1), ...
                "MATLAB:validators:mustBePositive");
        end

        function defaultRepresentationMatchesTheModelsOrder(tc)
            % A CONVENIENCE, not a constraint: the lag orders follow nStates
            % (nLagY = nStates, nLagU = nStates + 1), and any other representation
            % may be paired with this model instead.
            rep = tc.plainModel().defaultRepresentation();
            tc.verifyClass(rep, "rid.rep.Narx");
            tc.verifyEqual(rep.nLagY, 1);
            tc.verifyEqual(rep.nLagU, 2);
            tc.verifyEqual(rep.nk, 0);
            tc.verifyEqual(rep.nInputs, 1);
            tc.verifyTrue(rep.inputDifference);
            % The default coordinates: [u(k), du(k), yHat(k-1)].
            [~, dimName] = rep.bounds( ...
                struct("u1_k", [0 1], "du1_k", [-1 1], "y_km1", [0 1]));
            tc.verifyEqual(dimName, ["u1_k" "du1_k" "y_km1"]);
        end

        function describeIsANonEmptyString(tc)
            s = tc.plainModel().describe();
            tc.verifyClass(s, "string");
            tc.verifyGreaterThan(strlength(s), 0);
        end

    end

    methods (Access = private)
        function hist = arxHistory(~, a, b, rs)
            %ARXHISTORY  Data from y(k) = a*y(k-1) + b*u(k-1), for any pole a.
            %
            %   Generated directly rather than through the model, because the model
            %   cannot represent the poles these tests need it to reject.
            nSteps = 120;
            u = rand(rs, nSteps, 1);
            y = zeros(nSteps, 1);
            for kStep = 2:nSteps
                y(kStep) = a * y(kStep - 1) + b * u(kStep - 1);
            end
            hist = wellFormedHistory(u, "y", y, "tS", 0.1);
        end
    end

end
